/** Explicit foreground refresh, private credentials and local image export. Never contacts a server on open. */
public final class PhotoSourcesActivity extends PanelActivity {
    android.content.SharedPreferences prefs(){return getSharedPreferences("photo-sources",0);}
    File folder(){File f=new File(getCacheDir(),"photo-sources");f.mkdirs();return f;}
    @Override void home(){page("Personal photo sources","Choose your own Immich album or WebDAV folder. No refresh runs in the background. Preview and import a cached photo in Wallpaper Studio; your active wallpaper stays saved.",false);button("Connect or change source",this::configure);button("Photo & Art appearance",()->startActivity(new Intent(this,AmbientSettingsActivity.class)));button("Preview cached photos",()->startActivity(new Intent(this,AmbientActivity.class).putExtra("art-preview",false)));button("Museum art",()->startActivity(new Intent(this,ArtGalleryActivity.class)));button("Refresh selected source now",this::refresh);File[] files=folder().listFiles(f->f.getName().matches("[a-f0-9]{64}\\.jpg"));if(files==null||files.length==0)page.addView(text("No cached photos. Connect a source, then refresh it explicitly.",18));else{Arrays.sort(files,Comparator.comparing(File::getName));int n=0;for(File f:files){if(n++>=12)break;LinearLayout row=new LinearLayout(this);ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);android.graphics.BitmapFactory.Options o=new android.graphics.BitmapFactory.Options();o.inSampleSize=4;image.setImageBitmap(BitmapFactory.decodeFile(f.getPath(),o));row.addView(image,new LinearLayout.LayoutParams(dp(160),dp(90)));page.addView(row);button("Preview photo "+n+" in Wallpaper Studio",()->{setResult(RESULT_OK,new Intent().setData(Uri.parse("content://com.dvopenlabs.freedom.companions.snapshot/photo/"+f.getName().replace(".jpg",""))));finish();});}}button("Forget credentials and photos",()->{prefs().edit().clear().apply();clearPhotos();home();});}
    void clearPhotos(){PhotoLibrary.clear(this);}
    void configure(){var p=prefs();page("Connect your photos","Credentials stay in this companion. HTTPS verifies certificates. Local HTTP is unencrypted: use it only for a trusted server. Nothing is fetched until you press Refresh. Only one selected album/folder is requested, up to twelve photos.",true);Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Immich album","WebDAV folder"}));type.setSelection(p.getString("type","immich").equals("dav")?1:0);page.addView(type);EditText address=field("Server URL / WebDAV folder URL",p.getString("url",""),false),album=field("Immich album ID (UUID)",p.getString("album",""),false),tag=field("Optional Immich tag (exact name)",p.getString("tag",""),false),user=field("WebDAV username (leave empty for Immich)",p.getString("user",""),false),secret=field("Immich API key / WebDAV password",p.getString("secret",""),true);button("Choose an Immich album from this server",()->{if(type.getSelectedItemPosition()!=0){Toast.makeText(this,"Album browsing is for Immich; use a folder URL for WebDAV",Toast.LENGTH_LONG).show();return;}try{okhttp3.HttpUrl base=Network.url(address.getText().toString().trim(),true);if(base.query()!=null||base.fragment()!=null)throw new IllegalArgumentException();String key=secret.getText().toString();if(key.isEmpty()||key.length()>4096||key.contains("\r")||key.contains("\n"))throw new IllegalArgumentException();Map<String,String> headers=Collections.singletonMap("x-api-key",key);String endpoint=base.toString().replaceAll("/+$","")+"/api/albums";Toast.makeText(this,"Requesting this server’s album names only",Toast.LENGTH_SHORT).show();load(()->new JSONArray(new String(Network.requestWith("GET",endpoint,headers,null,true,1024*1024),StandardCharsets.UTF_8)),albums->{List<String> ids=new ArrayList<>(),names=new ArrayList<>();for(int i=0;i<Math.min(256,albums.length());i++){JSONObject row=albums.optJSONObject(i);if(row!=null&&PhotoSourcePolicy.album(row.optString("id"))){ids.add(row.optString("id"));names.add(PhotoLibrary.clean(row.optString("albumName","Untitled album"),120));}}if(ids.isEmpty()){Toast.makeText(this,"No accessible albums returned; you can enter an album ID",Toast.LENGTH_LONG).show();return;}new AlertDialog.Builder(this).setTitle("Choose an Immich album").setItems(names.toArray(new String[0]),(d,n)->album.setText(ids.get(n))).setNegativeButton("Cancel",null).show();},bad->Toast.makeText(this,"Album list unavailable. Check server/key, or enter the album ID",Toast.LENGTH_LONG).show());}catch(Exception bad){Toast.makeText(this,"Check server URL and API key first",Toast.LENGTH_LONG).show();}});button("Save source",()->{try{okhttp3.HttpUrl parsed=Network.url(address.getText().toString().trim(),true);if(parsed.query()!=null)throw new IllegalArgumentException();String url=parsed.toString();if(tag.getText().length()>80)throw new IllegalArgumentException();if(type.getSelectedItemPosition()==0&&!PhotoSourcePolicy.album(album.getText().toString().trim()))throw new IllegalArgumentException();String key=secret.getText().toString();if(key.isEmpty()||key.length()>4096||key.contains("\r")||key.contains("\n"))throw new IllegalArgumentException();clearPhotos();p.edit().putString("type",type.getSelectedItemPosition()==0?"immich":"dav").putString("url",url).putString("album",album.getText().toString().trim()).putString("tag",tag.getText().toString().trim()).putLong("last-refresh",0).putString("user",user.getText().toString()).putString("secret",key).apply();home();}catch(Exception bad){Toast.makeText(this,"Check the address, credentials and album ID",Toast.LENGTH_LONG).show();}});button("Cancel",this::home);}
    void refresh(){var p=prefs();if(p.getString("url","").isEmpty()){configure();return;}page("Refreshing photos","Only your configured album/folder is contacted. Leaving this panel stops the foreground job.",true);TextView status=text("Loading up to twelve photos…",18);page.addView(status);button("Back",this::home);int token=generation;Map<String,?> snapshot=p.getAll();load(()->PhotoLibrary.refresh(this,snapshot,()->visible&&generation==token),count->{p.edit().putLong("last-refresh",System.currentTimeMillis()).apply();status.setText(count+" photos cached. Your wallpaper stays saved.");button("View cached photos",this::home);},bad->status.setText("Refresh unavailable. Check the address, album/folder, tag and credentials. Existing cached photos remain available."));}
    @Override public void onBackPressed(){finish();}
}
